use std::collections::HashSet;

fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut res = Vec::with_capacity(nums.len());
    for x in nums {
        // HashSet::insert returns true if the value was not already present.
        if seen.insert(x) {
            res.push(x);
        }
    }
    res
}

